def test_get_all_subclasses_no_duplicates():
    from ansible.module_utils.common._utils import get_all_subclasses

    class Base:
        pass

    class Mid1(Base):
        pass

    class Mid2(Base):
        pass

    class Leaf(Mid1, Mid2):
        pass

    result = get_all_subclasses(Base)
    # Leaf should appear only once even though it inherits from two subclasses of Base
    result_list = list(result)
    assert result_list.count(Leaf) == 1
    assert Leaf in result
    assert Mid1 in result
    assert Mid2 in result

